// Catalog data layer — the full 239-product aajiva.com feed.
// Generated by scripts/import-catalog.mjs (factual fields only: no copied copy).
import catalog from './catalog.json';

export const CATALOG = catalog.products;
export const CATALOG_META = catalog.meta;

export const productById = (id) => CATALOG.find((p) => p.id === String(id));
export const productByHandle = (handle) => CATALOG.find((p) => p.handle === handle);

export const formatINR = (n) =>
  '₹' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 });

/* Shopify CDN images — ask for the size we actually render. */
export const imgUrl = (src, width) =>
  src.includes('width=') ? src : `${src}${src.includes('?') ? '&' : '?'}width=${width}`;

export const deepLink = (handle) => `https://aajiva.com/products/${handle}`;

export const discountPct = (p) =>
  p.compareAt && p.compareAt > p.price
    ? Math.round(((p.compareAt - p.price) / p.compareAt) * 100)
    : 0;

/* ── Zone → product_type mapping (every type has a home) ── */
export const ZONE_TYPES = {
  central: null, // bestsellers — rule below, may overlap type zones
  rings: ['Rings', 'Toe Rings'],
  gallery: ['Pendants', 'Earrings'],
  edits: ['Bracelets', 'Anklets'],
  gifting: ['Sets', 'Silver Rakhi'],
  entrance: [], // no products
};

/* Central Counter = 24 biggest discounts, ties broken by lower price.
 * Deterministic rule, recomputed from live catalog data. */
export function bestsellers(n = 24) {
  return [...CATALOG]
    .filter((p) => p.compareAt && p.compareAt > p.price)
    .sort((a, b) => {
      const da = (a.compareAt - a.price) / a.compareAt;
      const db = (b.compareAt - b.price) / b.compareAt;
      return db - da || a.price - b.price;
    })
    .slice(0, n);
}

export function zoneProducts(zoneId) {
  if (zoneId === 'central') return bestsellers();
  const types = ZONE_TYPES[zoneId];
  if (!types) return [];
  return CATALOG.filter((p) => types.includes(p.type));
}

