export function blurbFor(product) {
  const pool = BLURBS[product.type] || ['925 sterling silver, made for everyday wear.'];
  let h = 0;
  for (const c of product.id) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  return pool[h % pool.length];
}

